def _offset(value) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not -720 <= value <= 840:
        raise ZoneError(f"not an offset in minutes: {value!r}")
    return value


def parse_zone(name: str, z) -> Zone:
    if not isinstance(z, dict):
        raise ZoneError(f"zone {name}: not an object")
    std = _offset(z.get("std_offset_min"))
    dst = z.get("dst")
    if dst is None:
        return Zone(name, std)
    if not isinstance(dst, dict):
        raise ZoneError(f"zone {name}: dst is not an object")
    offset = _offset(dst.get("offset_min"))
    if offset == std:
        raise ZoneError(f"zone {name}: daylight saving offset equals the standard offset")
    return Zone(name, std, offset, _transition(dst.get("start")), _transition(dst.get("end")))


def load(raw: dict) -> dict[str, Zone]:
    if not isinstance(raw, dict):
        raise ZoneError("the zone table is not an object")
    return {name: parse_zone(name, z) for name, z in raw.items()}


def load_each(raw: dict) -> dict[str, "Zone | ZoneError"]:
    """Like load, but a broken zone is kept as its error: it only fails the
    events that use it (zones.md 1.4)."""
    if not isinstance(raw, dict):
        raise ZoneError("the zone table is not an object")
    out = {}
